# summarize each step: source, and type of message
def summ(m):
    if isinstance(m,str): return ('text', m[:80].replace(chr(10),' '))
    if isinstance(m,list):
        parts=[]
        for b in m:
            if isinstance(b,dict):
                t=b.get('type')
                if t=='text': parts.append('TEXT:'+b.get('text','')[:60].replace(chr(10),' '))
                elif t=='tool_use': parts.append('TOOL_USE['+b.get('name','')+']:'+json.dumps(b.get('input',{}))[:80])
                elif t=='tool_result':
                    c=b.get('content','')
                    if isinstance(c,list): c=' '.join(x.get('text','') if isinstance(x,dict) else str(x) for x in c)
                    parts.append('TOOL_RES:'+str(c)[:60].replace(chr(10),' '))
                else: parts.append(t or str(b)[:40])
        return ('list',parts)
    if isinstance(m,dict):
        return ('dict', m.get('type',str(list(m.keys()))))
    return ('?',str(m)[:60])
for st in s[:40]:
    typ,info=summ(st['message'])
    print(st['step_id'], st['source'], st['timestamp'][11:19], '|', info if typ!='list' else ' || '.join(info))
